package org.basaltmc.auth

import kotlin.test.Test
import kotlin.test.assertContentEquals
import kotlin.test.assertFalse

private fun hexToBytes(hex: String): ByteArray =
    ByteArray(hex.length / 2) { i -> hex.substring(i * 2, i * 2 + 2).toInt(16).toByte() }

/**
 * Golden vectors generated by running the real `javax.crypto.Cipher("AES/CFB8/NoPadding")` on a
 * JDK, with the same key reused as the IV (vanilla's own scheme). Covers both a single-call
 * encryption and the same plaintext fed through in five unevenly-sized chunks (1, 3, 7, 2, 27
 * bytes), to prove the shift-register state carries correctly across [Cfb8Cipher.update] calls
 * the way it needs to when fed arbitrary reads off a live socket.
 */
class Cfb8CipherTest {
    private val key = hexToBytes("030a11181f262d343b424950575e656c")
    private val plaintext =
        hexToBytes("010e1b2835424f5c697683909daab7c4d1deebf805121f2c394653606d7a8794a1aebbc8d5e2effc")
    private val ciphertext =
        hexToBytes("6c1b6bea478d92429e8275e235d7d9bce05b436fa777eb9bdb6b3052f887f5f9f04b3c6b1b456445")

    @Test
    fun encryptsInOneCallMatchesJdk() {
        val cipher = Cfb8Cipher.create(key)
        assertContentEquals(ciphertext, cipher.update(plaintext, encrypting = true))
    }

    @Test
    fun encryptsInUnevenChunksMatchesJdk() {
        val cipher = Cfb8Cipher.create(key)
        val chunkSizes = intArrayOf(1, 3, 7, 2, 27)
        var offset = 0
        val output = ByteArray(plaintext.size)
        for (size in chunkSizes) {
            val chunk = plaintext.copyOfRange(offset, offset + size)
            cipher.update(chunk, encrypting = true).copyInto(output, offset)
            offset += size
        }
        assertContentEquals(ciphertext, output)
    }

    @Test
    fun decryptsBackToPlaintext() {
        val cipher = Cfb8Cipher.create(key)
        assertContentEquals(plaintext, cipher.update(ciphertext, encrypting = false))
    }

    @Test
    fun encryptDecryptRoundTripAcrossIndependentCiphers() {
        val encryptor = Cfb8Cipher.create(key)
        val decryptor = Cfb8Cipher.create(key)
        val encrypted = encryptor.update(plaintext, encrypting = true)
        assertFalse(plaintext.contentEquals(encrypted))
        assertContentEquals(plaintext, decryptor.update(encrypted, encrypting = false))
    }
}
